async function loadSave(){let loaded=null;try{const r=await fetch('./api/save?_='+Date.now(),{cache:'no-store'});if(r.ok){loaded=await r.json();saveMode='server'}}catch{}if(!loaded){try{loaded=JSON.parse(localStorage.getItem('YaraAdventureV3Save')||'null')}catch{}saveMode='browser'}saveData=deepMerge(defaultSave(),loaded||{});saveData.version='3.9';ensureCharacterProfilesBase();ECON.ensureSave?.(saveData);applyOfflineGain();setStatus(saveMode==='server'?'✓ BAT 本地存档已连接：自动写入 saves/save_v3.json':'⚠ 未通过 BAT 启动：退出前请“导出存档”，下次可直接导入继续玩')}
function deepMerge(a,b){for(const k of Object.keys(b||{})){if(a[k]&&typeof a[k]==='object'&&!Array.isArray(a[k])&&b[k]&&typeof b[k]==='object'&&!Array.isArray(b[k]))deepMerge(a[k],b[k]);else a[k]=b[k]}return a}
function ensureCharacterProfilesBase(){saveData.characters=saveData.characters||{};const migrated=deepMerge(baseProfile(),saveData.profile||{});saveData.characters.Yara=deepMerge(migrated,saveData.characters.Yara||{});for(const p of Object.values(saveData.characters)){if(p){p.equipment=p.equipment||{};if(!('necklace' in p.equipment))p.equipment.necklace=null}}saveData.profile=saveData.characters.Yara;saveData.selectedCharacter=saveData.selectedCharacter||'Yara';ECON.ensureSave?.(saveData)}
function ensureCharacterProfiles(chars=[]){ensureCharacterProfilesBase();for(const c of chars){if(!c?.id)continue;const d=deepMerge(baseProfile(),c.growthDefaults||{});saveData.characters[c.id]=deepMerge(d,saveData.characters[c.id]||{});}saveData.profile=saveData.characters.Yara;markDirty();return saveData.characters}
async function writeSave(manual=false){saveData.lastSeen=Date.now();if(manual)saveData.manualSavedAt=Date.now();try{localStorage.setItem('YaraAdventureV3Save',JSON.stringify(saveData))}catch{}if(saveMode==='server'){try{await fetch('./api/save',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(saveData)});saveDirty=false;setStatus('✓ 已保存到本地文件 · '+new Date().toLocaleTimeString());return}catch{saveMode='browser'}}saveDirty=false;setStatus('已保存到浏览器缓存；建议同时导出 JSON 存档')}
function markDirty(){saveDirty=true}
function exportSave(){writeSave(true);const blob=new Blob([JSON.stringify(saveData,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`YaraAdventure_save_Lv${saveData.profile.level}_${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
async function importSaveFile(file){if(!file)return;try{const d=JSON.parse(await file.text());if((!d.profile&&!d.characters?.Yara)||!d.cultivation)throw new Error('不是有效的 V3 存档');saveData=deepMerge(defaultSave(),d);ensureCharacterProfilesBase();markDirty();await writeSave(true);refreshAllUI();renderLevels();alert('存档导入成功，可以直接继续冒险。')}catch(e){alert('导入失败：'+e.message)}}
