const REALMS=[['凡人',0],['练气',500],['筑基',1800],['金丹',5200],['元婴',12000],['化神',26000],['炼虚',52000]];
function realmInfo(){let idx=0;for(let i=0;i<REALMS.length;i++)if(saveData.cultivation.exp>=REALMS[i][1])idx=i;const cur=REALMS[idx],next=REALMS[Math.min(idx+1,REALMS.length-1)];return{idx,name:cur[0],start:cur[1],next:next[1],max:idx===REALMS.length-1}}
function cultivationRate(){return 1+realmInfo().idx*0.55+Math.floor(saveData.profile.level/5)*.25}
