function derivedStats(){const p=saveData.profile,s=p.stats,b=p.pillBonus,eq=ECON.equipmentBonus?.(saveData,'Yara')||{},sk=V38S.effects?.(saveData,'Yara')||{};return{maxHp:320+(p.level-1)*18+s.vit*42+b.hp+(eq.hp||0),maxMp:120+(p.level-1)*8+s.spi*22+b.mp+(eq.mp||0),speed:(320+s.agi*17+(eq.speed||0))*(1+(sk.dashDistancePct||0)*.05),jump:700+s.agi*15,power:(1+s.pow*.17+(p.level-1)*.03)*(1+(eq.attack||0)/100)*(1+(sk.damagePct||0)),defense:eq.defense||0,crit:.08+(eq.crit||0),cooldown:Math.min(.45,(eq.cooldown||0)+Math.max(0,-(sk.cooldownPct||0))),drop:eq.drop||0,skillEffects:sk}}
function expNeed(l){return 100+(l-1)*55}
function addExp(n){const p=saveData.profile;p.exp+=n;while(p.exp>=p.nextExp){p.exp-=p.nextExp;p.level++;p.skillPoints++;p.nextExp=expNeed(p.level)}markDirty()}

