  const e={type,...t,entityId,profileKey,elite,x,y:0,home:x,dir:-1,hp:t.hp,maxHp:t.hp,element:def?.element||'neutral',lootTable:def?.lootTable||null,statusEffects:{},dead:false,removed:false,deadElapsed:0,phase:rand(0,10),attackCd:rand(.65,1.15),action:null,reaction:null,stateMachine:new V31.StateMachine(V31.EnemyState.IDLE),attackCycle:-1};
  e.y=enemyYFor(x,e);return e
