  game.coins=L.coins.map((x,j)=>({x,y:730+(j%3)*45,r:12,taken:false,phase:rand(0,6)}));game.loot=[];game.projectiles=[];game.particles=[];game.cameraX=0;game.shake=0;game.flash=0;game.score=0;game.combo=0;game.comboTimer=0;game.cleared=false;game.deathAdvice=null;game.message=`第 ${L.id} 关 · ${L.name}`;game.messageTimer=2.4;game.startTime=performance.now();game.time=0;game.paused=false;pausePanel.classList.add('hidden');showView('gameView');game.running=true;game.last=performance.now();cancelAnimationFrame(game.frameReq);game.frameReq=requestAnimationFrame(loop)
