function setOverrideAnim(p,name,duration){p.overrideAnim={name,elapsed:0,duration:duration||clipDuration('Yara',name)}}
function updateOverrideAnim(p,dt){if(!p.overrideAnim)return;p.overrideAnim.elapsed+=dt;if(p.overrideAnim.elapsed>=p.overrideAnim.duration)p.overrideAnim=null}
function playerControlLocked(p){return !!p.dead||!!p.reaction||p.stateMachine?.isControlLocked?.()}
function applyPlayerReaction(kind,duration,sourceDir=0){const p=game.player;if(!p||p.dead)return;p.action=null;p.comboStep=0;p.comboQueued=false;p.inputBuffer.clear();const cfg=combatProfiles?.player?.reactions?.[kind]||{};const d=duration||cfg.duration||reactionDurations[kind]||.3;p.reaction={name:kind,elapsed:0,duration:d,next:cfg.next||null};p.stateMachine.set(kind,{lockMs:d*1000},true);if(kind==='hurt_light'){p.vx=sourceDir*130;p.vy=-90}else if(kind==='hurt_heavy'){p.vx=sourceDir*220;p.vy=-180}else if(kind==='knockback'){p.vx=sourceDir*420;p.vy=-250}else if(kind==='knockdown'){p.vx=sourceDir*330;p.vy=-320}else if(kind==='stun'){p.vx*=.2}}
function updatePlayerReaction(p,dt){if(!p.reaction)return false;p.reaction.elapsed+=dt;if(p.reaction.elapsed<p.reaction.duration)return true;const next=p.reaction.next;p.reaction=null;if(next==='getup'){const d=combatProfiles?.player?.reactions?.getup?.duration||.48;p.reaction={name:'getup',elapsed:0,duration:d,next:null};p.stateMachine.set('getup',{lockMs:d*1000},true);return true}p.stateMachine.set(p.grounded?'idle':'jump',{},true);return false}
function currentPlayerAnimation(p){if(p.dead)return'dead';if(p.reaction)return p.reaction.name;if(p.action)return p.action.animation;if(p.overrideAnim)return p.overrideAnim.name;if(!p.grounded)return p.vy<-80?'jump_up':'jump_fall';if(Math.abs(p.vx)>35)return'run';return'idle'}
function playerAnimationElapsed(p){if(p.reaction)return p.reaction.elapsed;if(p.action)return p.action.elapsed;if(p.overrideAnim)return p.overrideAnim.elapsed;return p.stateMachine?.elapsed||0}

function startPlayerAction(name,extra={}){const p=game.player,clip=V31.animations?.clip('Yara',name);if(!clip)return false;const meta={...(combatProfiles?.player?.attacks?.[name]||{}),...extra};p.action=new V33.ActionTimeline(name,clip,meta);p.stateMachine.set('attack',{lockMs:p.action.total()*1000},true);return true}
function startComboAttack(step){const p=game.player;step=clamp(step,1,3);p.comboStep=step;p.comboQueued=false;p.inputBuffer.clear('combo');return startPlayerAction(`attack_${step}`,{kind:'combo'})}
function queueBasicAttack(){const p=game.player;if(!p||p.dead||p.reaction)return;if(p.action){if(p.action.meta?.kind==='combo'&&p.comboStep<3){p.inputBuffer.push('combo',combatProfiles?.player?.comboBufferSeconds||.24);return}return}startComboAttack(1)}
function rollPlayerDamage(n){const p=game.player;return Math.round(n*(Math.random()<(p?.d?.crit||0)?1.5:1))}
function playerSkillMeta(meta={}){const sk=game.player?.d?.skillEffects||{};const out={...meta};if(out.kind==='combo'||String(out.id||'').startsWith('attack_'))out.skillScale=1+(sk.damagePct||0);else if(out.animation==='musou'||out.id==='musou')out.skillScale=1+(sk.musouDamagePct||0);else out.skillScale=1+(sk.coreDamagePct||0);return out}
function hitEnemyElemental(e,base,dir,reaction,meta={}){meta=playerSkillMeta(meta);const mult=V38E.multiplier?.(meta.element||game.player?.element||'metal',e.element||'neutral')||1,armorBonus=e.statusEffects?.armor_break?1.12:1;const damage=Math.max(1,Math.round(base*mult*armorBonus*(meta.skillScale||1)));hurtEnemy(e,damage,dir,reaction,meta);if(meta.status&&Math.random()<(0.38+(game.player?.d?.skillEffects?.statusChance||0))){V38E.applyStatus?.(e,meta.status,{baseDamage:damage,baseHp:e.maxHp,element:meta.element});if(meta.status==='stun')stunEnemy(e,.9)}return damage}
function processPlayerActionHitbox(p,a){if(a.phase!=='active')return;const meta=a.meta||{};if(meta.projectile){if(!a.projectileFired){a.projectileFired=true;game.projectiles.push({owner:'player',x:p.x+p.w/2+p.dir*48,y:p.y+45,w:30,h:20,vx:p.dir*760,vy:0,damage:rollPlayerDamage(34*p.d.power*(meta.damageScale||1)),reaction:meta.reaction||'hurt_heavy',element:meta.element||'water',status:meta.status||null,damageType:meta.damageType||'arcane',stagger:meta.stagger||0,life:2,color:'#9ee4ff'})}return}if(a.name==='musou'){if(!a.aoeFired){a.aoeFired=true;for(const e of game.enemies)if(!e.dead&&Math.abs(e.x-p.x)<(meta.radius||760))hitEnemyElemental(e,rollPlayerDamage(29*p.d.power*(meta.damageScale||3.3)),e.x>p.x?1:-1,meta.reaction||'knockdown',{...meta,id:a.name,animation:a.name})}return}
  const hb=meta.hitbox||{forward:140,height:135},damage=rollPlayerDamage(26*p.d.power*(meta.damageScale||1));
  for(const e of game.enemies){if(e.dead||a.hitSet.has(e))continue;const dx=e.x+e.w/2-(p.x+p.w/2),dy=Math.abs(e.y+e.h/2-(p.y+p.h/2));if(Math.abs(dx)<(hb.forward||140)&&dy<(hb.height||135)&&(Math.sign(dx||p.dir)===p.dir)){a.hitSet.add(e);hitEnemyElemental(e,damage,p.dir,meta.reaction||'hurt_light',{...meta,id:a.name,animation:a.name})}}
}
function updatePlayerAction(p,dt){if(!p.action)return;const a=p.action;a.tick(dt);if(a.meta?.kind==='combo'&&p.inputBuffer.consume('combo'))p.comboQueued=true;processPlayerActionHitbox(p,a);if(!a.finished)return;const comboNext=a.meta?.kind==='combo'&&p.comboQueued&&p.comboStep<3?p.comboStep+1:0;p.action=null;if(comboNext){startComboAttack(comboNext);return}p.comboStep=0;p.comboQueued=false;p.stateMachine.set(p.grounded?'idle':'jump',{},true)}
function startDash(){const p=game.player,meta=combatProfiles?.player?.attacks?.dash_L||{};if(p.dead||p.reaction||p.skillCd.l>0||p.mp<(meta.mp||12))return;if(p.action&&!p.action.canDashCancel())return;if(p.action){p.action=null;p.comboStep=0;p.comboQueued=false}p.mp-=meta.mp||12;p.skillCd.l=(meta.cooldown||2.3)*(1-(p.d.cooldown||0));p.dashTime=.2;p.invuln=meta.invuln||.36;p.vx=p.dir*(meta.speed||1200);setOverrideAnim(p,'dash_L');burst(p.x+p.w/2,p.y+48,18,'#ffc7dc')}
