function skillL(){startDash()}
function skillU(){const p=game.player,meta=combatProfiles?.player?.attacks?.skill_U||{};if(p.dead||p.reaction||p.action||p.skillCd.u>0||p.mp<(meta.mp||20))return;p.mp-=meta.mp||20;p.skillCd.u=(meta.cooldown||2.1)*(1-(p.d.cooldown||0));startPlayerAction('skill_U')}
function skillI(){const p=game.player,meta=combatProfiles?.player?.attacks?.skill_I||{};if(p.dead||p.reaction||p.action||p.skillCd.i>0||p.mp<(meta.mp||18))return;p.mp-=meta.mp||18;p.skillCd.i=(meta.cooldown||1.05)*(1-(p.d.cooldown||0));startPlayerAction('skill_I')}
function skillSpace(){const p=game.player,meta=combatProfiles?.player?.attacks?.musou||{};if(p.dead||p.reaction||p.action||p.skillCd.space>0||p.mp<(meta.mp||50))return;p.mp-=meta.mp||50;p.skillCd.space=(meta.cooldown||8)*(1-(p.d.cooldown||0));p.invuln=.75;game.flash=.14;game.shake=10;startPlayerAction('musou')}

function updatePlayerState(dt){const p=game.player;if(!p?.stateMachine)return;p.stateMachine.tick(dt);p.inputBuffer.tick(dt);updateOverrideAnim(p,dt);if(p.dead){p.stateMachine.set('dead',{},true);return}if(updatePlayerReaction(p,dt))return;if(p.action){updatePlayerAction(p,dt);return}if(p.dashTime>0)return;if(!p.grounded)p.stateMachine.set('jump',{},true);else if(Math.abs(p.vx)>35)p.stateMachine.set('run',{},true);else p.stateMachine.set('idle',{},true)}

function update(dt){const p=game.player,L=game.level;if(game.messageTimer>0)game.messageTimer-=dt;if(game.flash>0)game.flash-=dt;if(game.shake>0)game.shake=Math.max(0,game.shake-dt*24);if(game.comboTimer>0){game.comboTimer-=dt;if(game.comboTimer<=0)game.combo=0}['invuln','drop','dashTime'].forEach(k=>p[k]=Math.max(0,p[k]-dt));Object.keys(p.skillCd).forEach(k=>p.skillCd[k]=Math.max(0,p.skillCd[k]-dt));p.mp=Math.min(p.maxMp,p.mp+dt*(4+saveData.profile.stats.spi*.2));V38E.tickStatuses?.(p,dt,{damage:(n)=>{if(!p.dead){p.hp=Math.max(0,p.hp-n);if(p.hp<=0)damagePlayer(999,'hurt_heavy',0,{element:'neutral'})}},heal:(n)=>p.hp=Math.min(p.maxHp,p.hp+n)});if(p.dead){p.vy=Math.min(700,p.vy+1800*dt);p.y=Math.min(H+40,p.y+p.vy*dt);updateParticles(dt);updatePlayerState(dt);return}
  const rooted=V38E.rooted?.(p),locked=playerControlLocked(p),left=!rooted&&(keys.a||keys.arrowleft),right=!rooted&&(keys.d||keys.arrowright),down=keys.s||keys.arrowdown;if(!locked&&down&&p.grounded)p.drop=.18;const accel=p.grounded?2200:1400,max=(p.dashTime>0?1180:p.d.speed)*(V38E.speedMultiplier?.(p)||1);if(p.dashTime<=0&&!locked){if(left&&!right){if(p.dir!==-1&&p.grounded)setOverrideAnim(p,'turn',.12);p.vx-=accel*dt;p.dir=-1}else if(right&&!left){if(p.dir!==1&&p.grounded)setOverrideAnim(p,'turn',.12);p.vx+=accel*dt;p.dir=1}else p.vx*=Math.pow(p.grounded?.001:.08,dt);p.vx=clamp(p.vx,-max,max)}else if(locked)p.vx*=Math.pow(.12,dt);
  p.vy=Math.min(1200,p.vy+1800*dt);p.x=clamp(p.x+p.vx*dt,0,L.width-p.w);p.y+=p.vy*dt;p.wasGrounded=p.grounded;p.grounded=false;resolvePlatforms(p);if(!p.wasGrounded&&p.grounded&&!p.reaction&&!p.action)setOverrideAnim(p,'land',.14);if(p.y>H+160)damagePlayer(999,'knockdown',-p.dir);for(const hz of L.hazards)if(overlap(p,{x:hz[0],y:hz[1],w:hz[2],h:hz[3]}))damagePlayer(L.id===4||L.id===10?30:18,'hurt_heavy',-p.dir);
  if(game.roomController)game.roomController.update(dt,p,game.enemies,spawnRoomWave,v31Message);updateEnemies(dt);updateProjectiles(dt);updateCoins(dt);updateLoot(dt);updateParticles(dt);updatePlayerState(dt);
  const roomCam=game.roomController?.cameraX(W,L.width);game.cameraX=roomCam==null?clamp(lerp(game.cameraX,p.x-W*.38,1-Math.pow(.0007,dt)),0,L.width-W):lerp(game.cameraX,roomCam,1-Math.pow(.00003,dt));
  const portalOpen=game.roomController?game.roomController.allCleared():(game.boss&&game.boss.dead);if(portalOpen&&p.x>L.width-180&&!game.cleared)clearLevel()}
function resolvePlatforms(p){const prev=p.y+p.h-p.vy/60;if(p.drop>0)return;for(const [x,y,w] of game.level.platforms){if(p.x+p.w-12>x&&p.x+12<x+w&&p.vy>=0&&p.y+p.h>=y&&prev<=y+22){p.y=y-p.h;p.vy=0;if(!p.grounded)p.jumpsLeft=2;p.grounded=true}}}

function enemyAnimName(e){if(e.dead)return'dead';if(e.reaction)return e.reaction.name;if(e.action)return e.action.animation;if(Math.abs(game.player.x-e.x)>e.range*.85)return'run';return'idle'}
function enemyAnimElapsed(e){if(e.dead)return e.deadElapsed;if(e.reaction)return e.reaction.elapsed;if(e.action)return e.action.elapsed;return e.stateMachine?.elapsed||0}
function enemyAttackList(e){const p=combatProfiles?.enemies?.[e.profileKey];if(p)return(p.attacks||[]).filter(a=>!a.eliteOnly||e.elite);const atk=e.attack||'melee',statusByElement={fire:'burn',water:'slow',wood:'root',metal:'bleed',earth:'stun'},meta={id:'legacy_'+atk,animation:'attack',range:e.range||100,damageScale:1,reaction:atk==='slam'?'knockdown':atk==='dash'?'knockback':'hurt_light',element:e.element||'neutral',status:statusByElement[e.element]||null,damageType:atk==='slam'?'impact':(['fireball','iceball','feather'].includes(atk)?'arcane':'physical'),stagger:atk==='slam'?.45:.16,cooldown:[.9,1.35],timing:{windup:e.windup||.45,active:.16,recover:e.recover||.55}};if(['fireball','iceball','feather'].includes(atk))meta.projectile=true;if(atk==='slam')meta.quake=true;if(atk==='dash')meta.dash=65;return[meta]}
function chooseEnemyAttack(e){const list=enemyAttackList(e);if(!list.length)return null;e.attackCycle=(e.attackCycle+1)%list.length;return list[e.attackCycle]||list[0]}
function beginEnemyAttack(e){const a=chooseEnemyAttack(e);if(!a)return;const clip=V31.animations?.clip(e.entityId,a.animation||'attack');e.action=new V33.ActionTimeline(a.animation||'attack',clip,a);e.action.meta=a;e.stateMachine.set('attack',{lockMs:e.action.total()*1000},true)}
function enemyActiveHit(e,a){if(a.hitDone)return;const p=game.player,m=a.meta||{},dir=e.dir,sameY=Math.abs((e.y+e.h/2)-(p.y+p.h/2))<155;if(m.projectile){a.hitDone=true;game.projectiles.push({owner:'enemy',x:e.x+e.w/2,y:e.y+e.h*.45,w:26,h:18,vx:dir*430,vy:rand(-25,20),damage:Math.round(e.dmg*(m.damageScale||1)),reaction:m.reaction||'hurt_light',element:m.element||e.element||'neutral',status:m.status||null,damageType:m.damageType||'physical',stagger:m.stagger||0,life:3,color:'#ff9f72'});return}if(m.dash&&!a.dashed){a.dashed=true;e.x+=dir*m.dash}
  let box;if(m.quake)box={x:e.x-(m.range||200)*.45,y:e.y+e.h-90,w:e.w+(m.range||200)*.9,h:105};else box={x:dir>0?e.x+e.w-6:e.x-(m.range||e.range),y:e.y+12,w:m.range||e.range,h:e.h-24};
  if(sameY&&overlap(box,p)){a.hitDone=true;damagePlayer(Math.round(e.dmg*(m.damageScale||1)),m.reaction||'hurt_light',dir,{...m,element:m.element||e.element||'neutral'})}
}
function applyEnemyReaction(e,kind,duration,dir=0){if(e.dead)return;const d=duration||reactionDurations[kind]||.3;e.action=null;e.reaction={name:kind,elapsed:0,duration:d,next:kind==='knockdown'?'getup':null};e.stateMachine.set(kind,{lockMs:d*1000},true);if(kind==='hurt_light')e.x+=dir*12;else if(kind==='hurt_heavy')e.x+=dir*20;else if(kind==='knockback')e.x+=dir*(e.boss?24:56);else if(kind==='knockdown')e.x+=dir*(e.boss?18:45)}
function updateEnemyReaction(e,dt){if(!e.reaction)return false;e.reaction.elapsed+=dt;if(e.reaction.elapsed<e.reaction.duration)return true;const next=e.reaction.next;e.reaction=null;if(next==='getup'){const d=reactionDurations.getup;e.reaction={name:'getup',elapsed:0,duration:d,next:null};e.stateMachine.set('getup',{lockMs:d*1000},true);return true}e.stateMachine.set('idle',{},true);return false}
function hurtEnemy(e,dmg,dir,reaction='hurt_light',meta={}){if(e.dead)return;e.hp-=dmg;game.combo++;game.comboTimer=2.3;game.score+=Math.round(dmg*game.combo*.22);burst(e.x+e.w/2,e.y+e.h*.5,e.boss?16:9,'#ffe2a1');if(e.hp<=0){e.hp=0;e.dead=true;e.action=null;e.reaction=null;e.stateMachine.set('dead',{},true);game.score+=e.score;addExp(Math.round(e.score*.38));spawnLootForEnemy(e);markDirty();if(e.boss){game.message='镇守者已败 · 战利品已掉落';game.messageTimer=3}return}applyEnemyReaction(e,reaction,null,dir)}
function stunEnemy(e,duration=.9){if(!e||e.dead)return;applyEnemyReaction(e,'stun',duration,0)}
function damagePlayer(n,reaction='hurt_light',sourceDir=0,meta={}){const p=game.player;if(p.invuln>0||p.dead)return;const elem=meta.element||'neutral',em=V38E.multiplier?.(elem,p.element||'metal')||1,shield=V38E.damageTakenMultiplier?.(p)||1,defMul=V38E.defenseMultiplier?.(p)||1;n=Math.max(1,Math.round(n*em*shield*100/(100+(p.d?.defense||0)*defMul*3)));p.hp-=n;p.invuln=reaction==='hurt_light'?.35:.55;game.shake=reaction==='knockdown'?10:6;burst(p.x+p.w/2,p.y+48,12,'#ff776e');if(meta.status&&Math.random()<.34)V38E.applyStatus?.(p,meta.status,{baseDamage:n,baseHp:p.maxHp,element:elem});if(p.hp<=0){p.hp=0;p.dead=true;p.action=null;p.reaction=null;p.stateMachine.set('dead',{},true);p.vy=-450;game.deathAdvice=V38D.deathAdvice?.(saveData,p.d,game.level?.id)||null;game.message='气血耗尽';game.messageTimer=999;return}applyPlayerReaction(reaction,null,sourceDir||-p.dir)}
function respawn(){const old=game.player;game.player=makePlayer();game.player.hp=Math.max(150,Math.floor(old.maxHp*.6));game.player.mp=Math.max(60,Math.floor(old.maxMp*.65));game.cameraX=0;game.message='已回到本关起点';game.messageTimer=1.6}

function updateEnemies(dt){const p=game.player;for(const e of game.enemies){e.stateMachine?.tick(dt);e.phase+=dt;if(e.dead){e.deadElapsed+=dt;if(e.deadElapsed>clipDuration(e.entityId,'dead')+.2)e.removed=true;continue}V38E.tickStatuses?.(e,dt,{damage:(n)=>{if(!e.dead)hurtEnemy(e,n,0,'hurt_light',{element:'neutral'})},heal:(n)=>e.hp=Math.min(e.maxHp,e.hp+n)});if(updateEnemyReaction(e,dt))continue;e.attackCd=Math.max(0,e.attackCd-dt);const dx=p.x-e.x;e.dir=dx>=0?1:-1;if(e.action){e.action.tick(dt);if(e.action.phase==='active')enemyActiveHit(e,e.action);if(e.action.finished){const cd=e.action.meta?.cooldown||[.8,1.25];e.attackCd=rand(cd[0]||.8,cd[1]||1.25);e.action=null;e.stateMachine.set('idle',{},true)}}else{const dist=Math.abs(dx),attacks=enemyAttackList(e),maxRange=Math.max(e.range||80,...attacks.map(a=>a.range||0));if(dist<maxRange&&e.attackCd<=0)beginEnemyAttack(e);else if(dist<500||e.boss){if(dist>Math.min(maxRange*.78,150)){e.x+=Math.sign(dx)*e.speed*(V38E.speedMultiplier?.(e)||1)*(V38E.rooted?.(e)?0:1)*dt;e.stateMachine.set('run',{},true)}else e.stateMachine.set('idle',{},true)}else{e.x+=Math.sin(e.phase*.8)*e.speed*.08*dt;e.stateMachine.set('idle',{},true)}}e.x=clamp(e.x,e.home-190,e.home+220);if(e.flying)e.y=310+Math.sin(e.phase*1.4)*80;else e.y=enemyYFor(e.x,e)}}
function spawnLootForEnemy(e){if(!ECON.rollLoot)return;const drops=ECON.rollLoot(e)||[];for(const d of drops){const item=ECON.getItem?.(d.itemId);if(!item)continue;game.loot.push({itemId:d.itemId,qty:d.qty||1,x:e.x+e.w/2+rand(-26,26),y:e.y+e.h*.55,vx:rand(-80,80),vy:rand(-190,-80),age:0,taken:false});}}
function updateLoot(dt){const p=game.player;if(!p)return;for(const l of game.loot){if(l.taken)continue;l.age+=dt;l.vy+=620*dt;l.x+=l.vx*dt;l.y+=l.vy*dt;const floor=860;if(l.y>floor){l.y=floor;l.vy*=-.22;l.vx*=.7}const dx=(p.x+p.w/2)-l.x,dy=(p.y+p.h/2)-l.y,dist=Math.hypot(dx,dy);if(dist<260){const pull=dist<110?12:5;l.x+=dx*dt*pull;l.y+=dy*dt*pull}if(dist<42){l.taken=true;ECON.addItem?.(saveData,l.itemId,l.qty);const item=ECON.getItem?.(l.itemId);game.message=`获得 ${item?.name||l.itemId}${l.qty>1?' ×'+l.qty:''}`;game.messageTimer=1.4;markDirty();}}game.loot=game.loot.filter(x=>!x.taken&&x.age<25)}
function drawLoot(){const cam=game.cameraX;for(const l of game.loot){if(l.taken)continue;const item=ECON.getItem?.(l.itemId),im=images['item_'+l.itemId],x=l.x-cam,y=l.y+Math.sin(l.age*5)*5;if(x<-80||x>W+80)continue;ctx.save();const rar=ECON.state?.rarities?.[item?.rarity],color=rar?.color||'#ddd';ctx.shadowColor=color;ctx.shadowBlur=18;ctx.fillStyle='rgba(10,16,24,.68)';ctx.beginPath();ctx.arc(x,y,26,0,Math.PI*2);ctx.fill();ctx.strokeStyle=color;ctx.lineWidth=3;ctx.stroke();if(im&&im.complete)ctx.drawImage(im,x-21,y-21,42,42);ctx.shadowBlur=0;ctx.fillStyle='#fff';ctx.font='10px sans-serif';ctx.textAlign='center';ctx.fillText(item?.name||'',x,y+41);ctx.restore();}}
function updateProjectiles(dt){for(const pr of game.projectiles){pr.life-=dt;pr.x+=pr.vx*dt;pr.y+=pr.vy*dt;if(pr.owner==='player'){for(const e of game.enemies)if(!e.dead&&overlap(pr,e)){hitEnemyElemental(e,pr.damage,Math.sign(pr.vx),pr.reaction||'hurt_heavy',pr);pr.life=0;break}}else if(!game.player.dead&&overlap(pr,game.player)){damagePlayer(pr.damage,pr.reaction||'hurt_light',Math.sign(pr.vx),pr);pr.life=0}}game.projectiles=game.projectiles.filter(p=>p.life>0&&p.x>-100&&p.x<game.level.width+100&&p.y>-100&&p.y<H+100)}
function updateCoins(dt){const p=game.player;for(const c of game.coins){c.phase+=dt*3;if(!c.taken&&Math.abs(c.x-(p.x+p.w/2))<48&&Math.abs(c.y-(p.y+p.h/2))<80){c.taken=true;game.score+=100;p.mp=Math.min(p.maxMp,p.mp+8);addExp(10);saveData.cultivation.stones+=1;markDirty();burst(c.x,c.y,10,'#ffd65b')}}}
function burst(x,y,n,color){for(let i=0;i<n;i++)game.particles.push({x,y,vx:rand(-180,180),vy:rand(-240,90),life:rand(.25,.75),r:rand(2,6),color})}function updateParticles(dt){for(const q of game.particles){q.life-=dt;q.x+=q.vx*dt;q.y+=q.vy*dt;q.vy+=420*dt}game.particles=game.particles.filter(q=>q.life>0)}
function clearLevel(){
  game.cleared=true;const hp=game.player.hp/game.player.maxHp;let stars=1;if(hp>.55)stars++;if(game.time<190&&hp>.35)stars++;
  if(game.dungeonId){
    V39P.clearDungeon?.(saveData,game.dungeonId,stars);const rewards=V39P.grantDungeonReward?.(saveData,game.dungeonId)||[];addExp(90);game.message=`副本完成 · ${rewards.slice(0,2).join(' / ')}`;game.messageTimer=999;writeSave(false);return;
  }
  const lid=Number(game.level.id);saveData.stars[lid]=Math.max(saveData.stars[lid]||0,stars);saveData.unlocked=Math.max(saveData.unlocked,Math.min(20,lid+1));saveData.lastLevel=Math.min(20,lid+1);addExp(75+lid*14);saveData.cultivation.herbs+=8+lid;saveData.cultivation.stones+=18+lid*2;
  const found=V39P.discoverAfterLevel?.(saveData,lid)||[];writeSave(false);game.message=found.length?`通关 · 发现副本入口：${V39P.dungeon(found[0])?.name||found[0]}`:'通关';game.messageTimer=999
}
function drawBackground(){const L=game.level,im=images['bg'+L.id];ctx.fillStyle='#7694ad';ctx.fillRect(0,0,W,H);if(im&&im.complete){const cw=Math.min(im.width,Math.max(W,im.width*.82)),sx=clamp((game.cameraX/(L.width-W||1))*(im.width-cw),0,Math.max(0,im.width-cw));ctx.drawImage(im,sx,0,cw,im.height,0,0,W,H)}const rh=game.roomController?.hud?.();if(L.stageBoss&&rh&&rh.wave>=2){ctx.fillStyle='rgba(72,32,96,.18)';ctx.fillRect(0,0,W,H);ctx.fillStyle='rgba(255,220,170,.05)';for(let i=0;i<9;i++)ctx.fillRect(0,90+i*105,W,2)}}
function rr(x,y,w,h,r,fill,stroke){ctx.beginPath();ctx.roundRect(x,y,w,h,r);if(fill){ctx.fillStyle=fill;ctx.fill()}if(stroke){ctx.strokeStyle=stroke;ctx.stroke()}}
function drawWorld(){const cam=game.cameraX,L=game.level;for(const [x,y,w,h] of L.platforms){if(x+w<cam-100||x>cam+W+100)continue;const xx=x-cam;rr(xx,y,w,h,6,L.id===4||L.id===10?'#3b2e32':'#52604f');ctx.fillStyle=L.id===4||L.id===10?'#8b5334':'#86a16d';ctx.fillRect(xx,y,w,13)}for(const [x,y,w,h] of L.hazards){const xx=x-cam;if(xx+w<0||xx>W)continue;ctx.fillStyle=L.id===4||L.id===10?'#ff7d31':'#3d3333';ctx.fillRect(xx,y,w,h)}for(const c of game.coins){if(c.taken)continue;const x=c.x-cam,y=c.y+Math.sin(c.phase)*8;ctx.save();ctx.translate(x,y);ctx.fillStyle='#ffcc45';ctx.strokeStyle='#fff2a8';ctx.lineWidth=3;ctx.beginPath();ctx.arc(0,0,c.r,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.restore()}const portalOpen=game.roomController?game.roomController.allCleared():(game.boss&&game.boss.dead),gx=L.width-140-cam;ctx.save();ctx.translate(gx,775);ctx.globalAlpha=portalOpen?1:.32;ctx.strokeStyle=portalOpen?'#ffe4a0':'#70757f';ctx.lineWidth=11;ctx.beginPath();ctx.ellipse(0,75,50,90,0,0,Math.PI*2);ctx.stroke();ctx.globalAlpha=1;ctx.restore();drawLoot();drawBattleRoomBarriers()}
function drawBattleRoomBarriers(){if(!game.roomController)return;const cam=game.cameraX;for(const b of game.roomController.barriers()){const x=b.x-cam;ctx.save();const g=ctx.createLinearGradient(x-24,0,x+24,0);g.addColorStop(0,'rgba(255,170,210,0)');g.addColorStop(.5,'rgba(255,205,229,.72)');g.addColorStop(1,'rgba(255,170,210,0)');ctx.fillStyle=g;ctx.fillRect(x-30,170,60,740);ctx.strokeStyle='rgba(255,238,247,.85)';ctx.lineWidth=3;ctx.setLineDash([16,12]);ctx.beginPath();ctx.moveTo(x,180);ctx.lineTo(x,900);ctx.stroke();ctx.restore()}}
function drawEnemyTelegraph(e,x,y){if(!e.action||e.action.phase!=='windup')return;const m=e.action.meta||{},range=m.range||e.range||100;ctx.save();ctx.globalAlpha=.22+.08*Math.sin(performance.now()/70);ctx.fillStyle=e.elite?'#f6d36d':'#ff765c';if(m.quake){ctx.beginPath();ctx.ellipse(x+e.w/2,y+e.h-5,Math.min(150,range*.62),22,0,0,Math.PI*2);ctx.fill()}else{const dir=e.dir>0?1:-1;ctx.fillRect(dir>0?x+e.w:x-range,y+e.h-25,range,18)}ctx.restore()}
function drawEnemy(e,x,y){drawEnemyTelegraph(e,x,y);const anim=enemyAnimName(e),elapsed=enemyAnimElapsed(e),dir=e.dir<0?'left':'right';ctx.save();if(e.elite){ctx.shadowColor='#efc85e';ctx.shadowBlur=10}let drawn=actionRuntime?.draw(ctx,e.entityId,anim,dir,elapsed,x-20,y-35,e.w+40,e.h+55,{scale:e.boss?1.12:1.08});if(!drawn){const im=images['m_'+e.img];if(im&&im.complete&&im.naturalWidth){const cols=8,rows=6,cw=im.naturalWidth/cols,ch=im.naturalHeight/rows,col=Math.floor(elapsed*8)%cols,row=e.action?2:(Math.abs(game.player.x-e.x)>e.range*.85?1:0);ctx.save();ctx.translate(x+e.w/2,y+e.h/2);if(e.dir<0)ctx.scale(-1,1);ctx.drawImage(im,col*cw,row*ch,cw,ch,-(e.w+20)/2,-(e.h+30)/2,e.w+20,e.h+30);ctx.restore()}}ctx.restore();if(e.removed)return;const bw=e.boss?210:e.elite?108:86,rx=x+e.w/2-bw/2,ry=y-18;ctx.fillStyle='rgba(15,18,25,.72)';ctx.fillRect(rx,ry,bw,e.boss?13:8);ctx.fillStyle=e.boss?'#cc4851':e.elite?'#d7a73a':'#dd736a';ctx.fillRect(rx+2,ry+2,(bw-4)*clamp(e.hp/e.maxHp,0,1),e.boss?9:4);if(e.elite){ctx.fillStyle='#ffe8a1';ctx.font='bold 12px sans-serif';ctx.textAlign='center';ctx.fillText('精英 · 镇碑石卫',x+e.w/2,ry-5)}}
function drawPlayer(p,x,y){if(p.invuln>0&&Math.floor(p.invuln*22)%2===0)return;const anim=currentPlayerAnimation(p),elapsed=playerAnimationElapsed(p),dir=p.dir<0?'left':'right';ctx.save();let drawn=actionRuntime?.draw(ctx,'Yara',anim,dir,elapsed,x-48,y-65,168,190,{scale:1.05});if(!drawn){const im=images.player;if(im&&im.complete){const cw=im.naturalWidth/8,ch=im.naturalHeight/11,col=Math.floor(elapsed*8)%8;ctx.save();ctx.translate(x+p.w/2,y+p.h/2);if(p.dir<0)ctx.scale(-1,1);ctx.drawImage(im,col*cw,0,cw,ch,-76,-92,152,182);ctx.restore()}}ctx.restore()}
function drawEntities(){const cam=game.cameraX;for(const e of game.enemies){if(e.removed)continue;const x=e.x-cam;if(x>-280&&x<W+280)drawEnemy(e,x,e.y)}drawPlayer(game.player,game.player.x-cam,game.player.y);for(const pr of game.projectiles){const x=pr.x-cam;ctx.save();ctx.translate(x,pr.y);ctx.fillStyle=pr.color;ctx.shadowColor=pr.color;ctx.shadowBlur=18;ctx.beginPath();ctx.ellipse(0,0,pr.w,pr.h,0,0,Math.PI*2);ctx.fill();ctx.restore()}}
function drawEffects(){const cam=game.cameraX;for(const q of game.particles){ctx.globalAlpha=clamp(q.life*2,0,1);ctx.fillStyle=q.color;ctx.beginPath();ctx.arc(q.x-cam,q.y,q.r,0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1}
